package com.smartcoms.hms.controller;
import com.smartcoms.hms.entity.Appointment; import com.smartcoms.hms.repository.AppointmentRepository; import org.springframework.stereotype.*; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.*;
@Controller public class PublicController { private final AppointmentRepository appointments; public PublicController(AppointmentRepository a){appointments=a;} @GetMapping({"/","/home"}) String home(){return "public/home";} @GetMapping({"/about","/departments","/doctors","/facilities","/contact"}) String page(){return "public/page";} @GetMapping("/appointments") String booking(Model m){m.addAttribute("appointment",new Appointment());return "public/appointment";} @PostMapping("/appointments") String save(@ModelAttribute Appointment a){a.setStatus("Requested");appointments.save(a);return "redirect:/appointments?success";} @GetMapping("/login") String login(){return "login";} }
